-- MySQL 8 schema. Runtime ORM models mirror these entities; all application queries use SQLAlchemy.
CREATE TABLE users (id BIGINT AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE career_sessions (id CHAR(36) PRIMARY KEY, user_id BIGINT NOT NULL, stage VARCHAR(32) NOT NULL DEFAULT 'intake', profile_json JSON NOT NULL, summary TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_sessions_user_updated (user_id, updated_at));
CREATE TABLE conversation_turns (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id CHAR(36) NOT NULL, role VARCHAR(16) NOT NULL, content TEXT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (session_id) REFERENCES career_sessions(id) ON DELETE CASCADE, INDEX idx_turn_session (session_id, id));
CREATE TABLE recommendations (id BIGINT AUTO_INCREMENT PRIMARY KEY, session_id CHAR(36) NOT NULL, career_title VARCHAR(160) NOT NULL, rationale TEXT NOT NULL, sources_json JSON NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (session_id) REFERENCES career_sessions(id) ON DELETE CASCADE, INDEX idx_rec_session (session_id));
CREATE TABLE refresh_tokens (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, jti CHAR(36) NOT NULL UNIQUE, revoked BOOLEAN NOT NULL DEFAULT FALSE, expires_at TIMESTAMP NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_refresh_user (user_id));
CREATE TABLE password_resets (id BIGINT AUTO_INCREMENT PRIMARY KEY, user_id BIGINT NOT NULL, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMP NOT NULL, used BOOLEAN NOT NULL DEFAULT FALSE, FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE, INDEX idx_reset_user (user_id));
